template<class T>void visit(const Context& c,const string& f,T* const& p){value(c.dataset,c.key,f+".present",p!=nullptr);if(p)visit(c,f,*p);}
template<class T,size_t N>void visit(const Context& c,const string& f,const T(&p)[N]){value(c.dataset,c.key,f+".count",N);for(size_t i=0;i<N;++i)visit(c,f+"["+to_string(i)+"]",p[i]);}
template<class T,class A>void visit(const Context& c,const string& f,const vector<T,A>& p){value(c.dataset,c.key,f+".count",p.size());for(size_t i=0;i<p.size();++i)visit(c,f+"["+to_string(i)+"]",p[i]);}
template<class K,class V,class C,class A>void visit(const Context& c,const string& f,const map<K,V,C,A>& p){value(c.dataset,c.key,f+".count",p.size());size_t i=0;for(const auto& entry:p){string path=f+"["+to_string(i++)+"]";visit(c,path+".key",entry.first);visit(c,path+".value",entry.second);}}
template<class K,class C,class A>void visit(const Context& c,const string& f,const set<K,C,A>& p){value(c.dataset,c.key,f+".count",p.size());size_t i=0;for(const auto& entry:p)visit(c,f+"["+to_string(i++)+"]",entry);}
#include "startup_fields.inc"
void readSkillLevels(const string& root){
    // Only visit array elements which the original InitTSKILLPOINT initialized.
    CFile file(asset(root,"Tcd/TSkillPoint.tcd").c_str(),CFile::modeRead|CFile::typeBinary);CArchive ar(&file,CArchive::load);
    WORD count;ar>>count;for(WORD i=0;i<count;++i){WORD id;BYTE level,point,group,prev;ar>>id>>level>>point>>group>>prev;skillLevels[id].insert(level);}
}

std::ofstream loadLog;
void loaded(const string& file,const char* loader){loadLog<<file<<'\t'<<loader<<"\tPASS\n";loadLog.flush();if(!loadLog)throw runtime_error("coverage write failed");}
void ensureInput(const string& root,const char* file){CFile input(asset(root,file).c_str(),CFile::modeRead|CFile::typeBinary);if(input.GetLength()==0)throw runtime_error(string("empty input: ")+file);}
void begin(const char* loader){std::cerr<<"BEGIN "<<loader<<std::endl;}
void ensureMantleVersion(const string& root){CFile file(asset(root,"Tcd/TMantleCoord.tcd").c_str(),CFile::modeRead|CFile::typeBinary);CArchive ar(&file,CArchive::load);DWORD version;ar>>version;if(version!=MANTLECOORD_VER&&version!=MANTLECOORD_VER_OLD)throw runtime_error("unsupported mantle coordinate version");}
